from html import escape

def contact_form(fr):
    def t(en, french): return french if fr else en
    def field(name,label,kind='text',required=False,options=None):
        attrs=f'id="enquiry-{name}" name="{name}" aria-describedby="error-{name}"'+(' required' if required else '')
        if options:
            control=f'<select {attrs}>'+''.join(f'<option value="{escape(v)}">{escape(l)}</option>' for v,l in options)+'</select>'
        elif kind=='textarea': control=f'<textarea {attrs} rows="4" maxlength="500"></textarea>'
        else: control=f'<input {attrs} type="{kind}" maxlength="150" autocomplete="{name if name in ["name","email","tel"] else "off"}">'
        return f'<div class="form-field"><label for="enquiry-{name}">{label}{" *" if required else ""}</label>{control}<span class="field-error" id="error-{name}"></span></div>'
    topics=[('',t('Choose a topic','Choisissez un sujet')),('Real estate',t('Real estate','Immobilier')),('Family',t('Family & separation','Famille et séparation')),('Estates',t('Wills & estates','Testaments et successions')),('Business',t('Business & contracts','Entreprises et contrats')),('Tenancies',t('Residential tenancies','Location résidentielle')),('Disputes',t('Civil disputes','Litiges civils')),('Criminal law',t('Criminal law','Droit criminel')),('Other',t('Other / unsure','Autre / incertain'))]
    fields=field('name',t('Your name','Votre nom'),required=True)+field('email',t('Email','Courriel'),'email',True)+field('tel',t('Phone (optional)','Téléphone (facultatif)'),'tel')+field('topic',t('General topic','Sujet général'),required=True,options=topics)+field('language',t('Preferred appointment language','Langue de rendez-vous souhaitée'),options=[('English',t('English','Anglais')),('Ukrainian',t('Ukrainian','Ukrainien')),('Russian',t('Russian','Russe'))])+field('message',t('Brief note (optional, 500 characters maximum)','Note brève (facultative, 500 caractères maximum)'),'textarea')
    privacy='/fr/privacy/' if fr else '/privacy/'
    return f'''<section class="enquiry-section"><h2>{t('Send an enquiry','Envoyer une demande')}</h2><p id="form-guidance">{t('Share only the general topic. Do not include confidential facts, identification numbers or documents. An enquiry does not create a lawyer-client relationship or pause a deadline. Fields marked * are required.','Indiquez uniquement le sujet général. N’incluez pas de faits confidentiels, de numéros d’identification ni de documents. Une demande ne crée pas de relation avocat-client et ne suspend aucun délai. Les champs marqués * sont obligatoires.')}</p>
<form id="enquiry-form" action="https://formspree.io/f/mjykzlez" method="POST" aria-describedby="form-guidance"><input type="hidden" name="_subject" value="HalifaxLaw.ca — new enquiry"><input type="hidden" name="website_language" value="{'fr' if fr else 'en'}"><div class="form-trap" aria-hidden="true"><label>Leave this empty<input name="_gotcha" tabindex="-1" autocomplete="off"></label></div><fieldset><legend class="sr-only">{t('Enquiry details','Détails de la demande')}</legend>{fields}<div class="form-field"><label class="consent-label"><input id="enquiry-consent" name="consent" type="checkbox" value="Contact about this enquiry" required aria-describedby="error-consent"><span>{t('I agree to send these details through Formspree to Kostyantyn Mykhalchenko at Pavel Boubnov – Barrister & Solicitor, so the practice can respond to my enquiry. This is not marketing consent.','J’accepte de transmettre ces renseignements par Formspree à Kostyantyn Mykhalchenko, chez Pavel Boubnov – Barrister & Solicitor, afin que le cabinet réponde à ma demande. Ceci ne constitue pas un consentement au marketing.')} *</span></label><span class="field-error" id="error-consent"></span></div><p><a href="{privacy}">{t('How your information is handled','Traitement de vos renseignements')}</a> · <a href="https://formspree.io/legal/privacy-policy/">{t('Formspree privacy policy','Confidentialité de Formspree')}</a></p><button class="button" type="submit">{t('SEND ENQUIRY','ENVOYER LA DEMANDE')}</button></fieldset><p id="form-status" role="status" tabindex="-1"></p></form></section>'''
